create policy "Enable insert for authenticated users only"
on "public"."alerts"
as permissive
for insert
to authenticated
with check (true);


create policy "Enable read access for all users"
on "public"."alerts"
as permissive
for select
to public
using (true);


create policy "Enable read for authenticated users only"
on "public"."alerts"
as permissive
for select
to authenticated
using (true);


create policy "Update only user's own"
on "public"."alerts"
as permissive
for update
to authenticated
using ((EXISTS ( SELECT 1
   FROM users u
  WHERE ((u.id = alerts.user_id) AND ((u.auth_id)::text = (auth.uid())::text)))))
with check ((EXISTS ( SELECT 1
   FROM users u
  WHERE ((u.id = alerts.user_id) AND ((u.auth_id)::text = (auth.uid())::text)))));


create policy "Enable insert for authenticated users only"
on "public"."alerts_verifications"
as permissive
for all
to authenticated
using (true)
with check (true);


create policy "Enable read access for all users"
on "public"."alerts_verifications"
as permissive
for select
to public
using (true);


create policy "Enable read access for all users"
on "public"."roles"
as permissive
for select
to public
using (true);


create policy "Enable read access for all users"
on "public"."tiers"
as permissive
for select
to public
using (true);


create policy "Enable delete for users based on user_id"
on "public"."users"
as permissive
for delete
to public
using ((( SELECT auth.uid() AS uid) = auth_id));


create policy "Enable insert for authenticated users only"
on "public"."users"
as permissive
for insert
to authenticated
with check (true);


create policy "Enable select for authenticated users only"
on "public"."users"
as permissive
for select
to authenticated
using (true);


create policy "Enable all for authenticated users only"
on "public"."users_devices"
as permissive
for all
to authenticated
using (true)
with check (true);


create policy "Enable insert for authenticated users only"
on "public"."users_received_alerts"
as permissive
for all
to authenticated
using (true)
with check (true);


-- Ensure pg_net exists
create extension if not exists pg_net with schema extensions;

-- Trigger function
create or replace function public.notify_alert_status()
returns trigger
language plpgsql
as $$
begin
  perform net.http_post(
    url := 'https://alertly-backend-api-server.onrender.com/api/webhooks/alerts-status',
    body := jsonb_build_object(
      'type', TG_OP,
      'table', TG_TABLE_NAME,
      'schema', TG_TABLE_SCHEMA,
      'record', to_jsonb(NEW),
      'old_record', case when TG_OP = 'UPDATE' then to_jsonb(OLD) else null end
    ),
    headers := '{"Content-Type":"application/json"}'::jsonb,
    timeout_milliseconds := 5000
  );
  return NEW;
end;
$$;

-- Recreate trigger
drop trigger if exists alert_status on public.alerts;
create trigger alert_status
after insert or update on public.alerts
for each row
execute function public.notify_alert_status();
